package runtimeacp_test

import (
	"context"
	"encoding/json"
	"testing"

	"github.com/hecatehq/acp-adapter-kit/runtimeacp"
)

func TestAuthenticateSendsMethodID(t *testing.T) {
	client := &recordingACPClient{result: json.RawMessage(`{}`)}

	if err := runtimeacp.Authenticate(context.Background(), client, runtimeacp.AuthenticateParams{MethodID: "agent-login"}); err != nil {
		t.Fatalf("Authenticate returned error: %v", err)
	}
	if client.method != "authenticate" {
		t.Fatalf("method = %q, want authenticate", client.method)
	}
	var params runtimeacp.AuthenticateParams
	mustJSONRoundTrip(t, client.params, &params)
	if params.MethodID != "agent-login" {
		t.Fatalf("MethodID = %q, want agent-login", params.MethodID)
	}
}

func TestLogoutSendsEmptyRequest(t *testing.T) {
	client := &recordingACPClient{result: json.RawMessage(`{}`)}

	if err := runtimeacp.Logout(context.Background(), client); err != nil {
		t.Fatalf("Logout returned error: %v", err)
	}
	if client.method != "logout" {
		t.Fatalf("method = %q, want logout", client.method)
	}
}

type recordingACPClient struct {
	method string
	params any
	result json.RawMessage
}

func (c *recordingACPClient) Request(_ context.Context, method string, params any) (json.RawMessage, error) {
	c.method = method
	c.params = params
	return c.result, nil
}

func mustJSONRoundTrip(t testing.TB, value any, target any) {
	t.Helper()
	raw, err := json.Marshal(value)
	if err != nil {
		t.Fatalf("marshal params: %v", err)
	}
	if err := json.Unmarshal(raw, target); err != nil {
		t.Fatalf("unmarshal params: %v", err)
	}
}

//go:build darwin

package commandbridge

import (
	"context"
	"os"
	"os/exec"
	"testing"

	"golang.org/x/sys/unix"
)

func TestDarwinPromptResourcesRejectUnsafeAncestorAndStripInheritedACLs(t *testing.T) {
	parent := t.TempDir()
	cmd := exec.Command("/bin/chmod", "+a", "everyone allow read,list,search,file_inherit,directory_inherit", parent)
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("install inheritable ACL: %v (%s)", err, output)
	}
	if _, stage, err := preparePromptResources(context.Background(), oneImagePrompt(), PromptResourceLimits{}, parent, nil); stage != nil || err == nil {
		t.Fatalf("prepare result stage=%#v err=%v, want ACL-bearing ancestor rejection", stage, err)
	}
	stagePath := parent + "/inherited-stage"
	if err := os.Mkdir(stagePath, 0o700); err != nil {
		t.Fatal(err)
	}
	stageFile, err := os.Open(stagePath)
	if err != nil {
		t.Fatal(err)
	}
	defer stageFile.Close()
	if err := verifyDarwinPromptResourceACLAbsent(stageFile); err == nil {
		t.Fatal("inherited stage unexpectedly has no ACL before hardening")
	}
	filePath := stagePath + "/input.bin"
	file, err := os.OpenFile(filePath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	if err := securePromptResourceDirectoryFile(stageFile, 0o700); err != nil {
		t.Fatalf("strip inherited stage ACL: %v", err)
	}
	if err := securePrivatePromptResourceFile(file, 0o600); err != nil {
		t.Fatalf("strip inherited file ACL before bytes: %v", err)
	}
}

func TestStripDarwinPromptResourceACLRemovesACLFromRetainedFile(t *testing.T) {
	path := t.TempDir() + "/resource.bin"
	if err := os.WriteFile(path, []byte("private"), 0o600); err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command("/bin/chmod", "+a", "everyone allow read", path)
	if output, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("install file ACL: %v (%s)", err, output)
	}
	file, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	if err := verifyDarwinPromptResourceACLAbsent(file); err == nil {
		t.Fatal("test resource unexpectedly has no ACL before stripping")
	}
	if err := stripDarwinPromptResourceACL(file); err != nil {
		t.Fatalf("strip retained file ACL: %v", err)
	}
	if err := verifyDarwinPromptResourceACLAbsent(file); err != nil {
		t.Fatalf("ACL remains after stripping: %v", err)
	}
}

func TestDarwinPromptResourceFilesystemRequiresLocalMount(t *testing.T) {
	file, err := os.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	if err := verifyDarwinPromptResourceLocalFilesystem(file); err != nil {
		t.Fatalf("verify native temporary filesystem: %v", err)
	}
	if darwinPromptResourceFilesystemIsLocal(0) {
		t.Fatal("zero mount flags unexpectedly satisfy local-filesystem policy")
	}
	if !darwinPromptResourceFilesystemIsLocal(unix.MNT_LOCAL) {
		t.Fatal("MNT_LOCAL mount flags were rejected")
	}
}

//go:build linux

package commandbridge

import (
	"os"
	"testing"

	"golang.org/x/sys/unix"
)

func TestLinuxPromptResourceFilesystemAllowlist(t *testing.T) {
	for _, magic := range []uint32{
		unix.EXT4_SUPER_MAGIC,
		unix.XFS_SUPER_MAGIC,
		unix.BTRFS_SUPER_MAGIC,
		unix.TMPFS_MAGIC,
		unix.OVERLAYFS_SUPER_MAGIC,
		unix.RAMFS_MAGIC,
		unix.F2FS_SUPER_MAGIC,
	} {
		if !linuxPromptResourceFilesystemAllowed(magic) {
			t.Errorf("filesystem magic %#x was not allowed", magic)
		}
	}
	for _, magic := range []uint32{
		unix.NFS_SUPER_MAGIC,
		unix.CIFS_SUPER_MAGIC,
		unix.SMB2_SUPER_MAGIC,
		unix.FUSE_SUPER_MAGIC,
		unix.V9FS_MAGIC,
		0x7fffffff,
	} {
		if linuxPromptResourceFilesystemAllowed(magic) {
			t.Errorf("remote or unknown filesystem magic %#x was allowed", magic)
		}
	}
}

func TestLinuxPromptResourceFilesystemAcceptsNativeTempDirectory(t *testing.T) {
	file, err := os.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	if err := verifyLinuxPromptResourceLocalFilesystem(file); err != nil {
		t.Fatalf("verify native temporary filesystem: %v", err)
	}
}

//go:build darwin || linux

package commandbridge

import (
	"context"
	"encoding/base64"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/hecatehq/acp-adapter-kit/runtimeacp"
)

func TestPreparePromptResourcesRejectsUnsafeAncestor(t *testing.T) {
	root := t.TempDir()
	unsafeParent := filepath.Join(root, "unsafe")
	if err := os.Mkdir(unsafeParent, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(unsafeParent, 0o777); err != nil {
		t.Fatal(err)
	}
	_, stage, err := preparePromptResources(context.Background(), oneImagePrompt(), PromptResourceLimits{}, unsafeParent, nil)
	var stagingErr *promptResourceStagingError
	if stage != nil || !errors.As(err, &stagingErr) || stagingErr.operation != "validate prompt resource temporary parent" {
		t.Fatalf("prepare result stage=%#v err=%v, want operational unsafe-ancestor rejection", stage, err)
	}
}

func TestPromptResourceStageGuardRetriesTransientCleanupInCall(t *testing.T) {
	prepared, stage, err := preparePromptResources(context.Background(), oneImagePrompt(), PromptResourceLimits{}, t.TempDir(), nil)
	if err != nil || len(prepared.Prompt) != 1 || stage == nil {
		t.Fatalf("prepare result stage=%#v err=%v", stage, err)
	}
	anchor := stage.anchor
	attempts := 0
	stage.cleanupHook = func(path string) error {
		attempts++
		if attempts == 1 {
			return errors.New("transient failure")
		}
		return nil
	}
	if err := stage.cleanup(); err != nil {
		t.Fatalf("bounded cleanup retry: %v", err)
	}
	if attempts != 2 {
		t.Fatalf("cleanup attempts = %d, want 2", attempts)
	}
	if _, err := os.Stat(anchor); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("private anchor still exists after bounded retry: %v", err)
	}
}

func TestPromptResourceCleanupDoesNotMutateReplacementPermissions(t *testing.T) {
	_, stage, err := preparePromptResources(context.Background(), oneImagePrompt(), PromptResourceLimits{}, t.TempDir(), nil)
	if err != nil || stage == nil {
		t.Fatalf("prepare result stage=%#v err=%v", stage, err)
	}
	originalPath := stage.dir
	movedPath := originalPath + "-moved"
	if err := os.Rename(originalPath, movedPath); err != nil {
		t.Fatal(err)
	}
	if err := os.Mkdir(originalPath, 0o555); err != nil {
		t.Fatal(err)
	}
	guard := stage.guard.(*unixPromptResourceStageGuard)
	if err := guard.Cleanup(nil); err == nil {
		t.Fatal("cleanup succeeded after stage replacement")
	}
	replacement, err := os.Stat(originalPath)
	if err != nil {
		t.Fatalf("stat replacement: %v", err)
	}
	if got := replacement.Mode().Perm(); got != 0o555 {
		t.Fatalf("replacement mode = %o, want unchanged 555", got)
	}
	if err := securePromptResourceDirectoryFile(guard.stage.file, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := guard.close(); err != nil {
		t.Fatal(err)
	}
	stage.guard = nil
	if err := os.Chmod(stage.anchor, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.RemoveAll(stage.anchor); err != nil {
		t.Fatalf("test cleanup: %v", err)
	}
}

func oneImagePrompt() runtimeacp.PromptParams {
	return runtimeacp.PromptParams{Prompt: []runtimeacp.ContentBlock{{
		Type:     "image",
		MimeType: "image/png",
		Data:     base64.StdEncoding.EncodeToString([]byte("image")),
	}}}
}

//go:build windows

package commandbridge

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"unicode/utf16"
	"unsafe"

	"github.com/hecatehq/acp-adapter-kit/runtimeacp"
	"golang.org/x/sys/windows"
)

func TestSecurePromptResourceStageUsesProtectedInheritablePrivateDACL(t *testing.T) {
	dir := t.TempDir()
	if err := securePromptResourceStage(dir); err != nil {
		t.Fatalf("securePromptResourceStage: %v", err)
	}
	allowed, err := promptStageAllowedSIDs()
	if err != nil {
		t.Fatal(err)
	}
	descriptor, err := windows.GetNamedSecurityInfo(dir, windows.SE_FILE_OBJECT, windows.DACL_SECURITY_INFORMATION)
	if err != nil {
		t.Fatal(err)
	}
	control, _, err := descriptor.Control()
	if err != nil {
		t.Fatal(err)
	}
	if control&windows.SE_DACL_PROTECTED == 0 {
		t.Fatal("stage DACL is not protected")
	}
	assertPromptStageACLEntries(t, descriptor, allowed, true)

	child := filepath.Join(dir, "input.bin")
	childFile, err := createPrivatePromptResourceFile(child)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Rename(child, child+".moved"); err == nil {
		_ = os.Rename(child+".moved", child)
		_ = childFile.Close()
		t.Fatal("new private child allowed rename before its retained identity handle was installed")
	}
	if err := securePrivatePromptResourceFile(childFile, 0o600); err != nil {
		_ = childFile.Close()
		t.Fatalf("verify explicit protected child DACL before write: %v", err)
	}
	if _, err := childFile.Write([]byte("private")); err != nil {
		_ = childFile.Close()
		t.Fatal(err)
	}
	if err := childFile.Close(); err != nil {
		t.Fatal(err)
	}
	childDescriptor, err := windows.GetNamedSecurityInfo(child, windows.SE_FILE_OBJECT, windows.DACL_SECURITY_INFORMATION)
	if err != nil {
		t.Fatal(err)
	}
	assertPromptStageACLEntries(t, childDescriptor, allowed, false)
}

func TestWindowsPromptResourceDirectoryInfoLayoutAndBounds(t *testing.T) {
	for size := 1; size <= 64*1024; size *= 2 {
		buffer := alignedWindowsPromptResourceDirectoryBuffer(size)
		if len(buffer) != size {
			t.Fatalf("aligned directory buffer length = %d, want %d", len(buffer), size)
		}
		if address := uintptr(unsafe.Pointer(&buffer[0])); address%8 != 0 {
			t.Fatalf("aligned directory buffer address %#x is not 8-byte aligned", address)
		}
	}

	if got := unsafe.Offsetof(windowsFileFullDirectoryInfo{}.FileNameLength); got != 60 {
		t.Fatalf("FileNameLength offset = %d, want 60", got)
	}
	if got := unsafe.Offsetof(windowsFileFullDirectoryInfo{}.EaSize); got != 64 {
		t.Fatalf("EaSize offset = %d, want 64", got)
	}
	if got := unsafe.Offsetof(windowsFileFullDirectoryInfo{}.FileName); got != 68 {
		t.Fatalf("FileName offset = %d, want 68", got)
	}
	if got := unsafe.Sizeof(windowsFileFullDirectoryInfo{}); got != 72 {
		t.Fatalf("FILE_FULL_DIR_INFO size = %d, want 72", got)
	}

	valid := windowsPromptResourceDirectoryTestBuffer("notes-λ.txt", 0, 0)
	names, err := decodeWindowsPromptResourceDirectoryEntries(valid, 1)
	if err != nil || len(names) != 1 || names[0] != "notes-λ.txt" {
		t.Fatalf("decode valid Unicode entry = %#v, %v", names, err)
	}
	if _, err := decodeWindowsPromptResourceDirectoryEntries(valid, 0); err == nil {
		t.Fatal("entry beyond expected bound was accepted")
	}
	dot := windowsPromptResourceDirectoryTestBuffer(".", 0, 0)
	if names, err := decodeWindowsPromptResourceDirectoryEntries(dot, 0); err != nil || len(names) != 0 {
		t.Fatalf("decode dot entry = %#v, %v", names, err)
	}

	oversized := windowsPromptResourceDirectoryTestBuffer("x", 0, 0)
	(*windowsFileFullDirectoryInfo)(unsafe.Pointer(&oversized[0])).FileNameLength = 0x7ffffffe
	if _, err := decodeWindowsPromptResourceDirectoryEntries(oversized, 1); err == nil {
		t.Fatal("oversized name length was accepted")
	}
	odd := windowsPromptResourceDirectoryTestBuffer("x", 0, 0)
	(*windowsFileFullDirectoryInfo)(unsafe.Pointer(&odd[0])).FileNameLength = 3
	if _, err := decodeWindowsPromptResourceDirectoryEntries(odd, 1); err == nil {
		t.Fatal("odd name length was accepted")
	}
	overlap := windowsPromptResourceDirectoryTestBuffer("x", 68, 80)
	if _, err := decodeWindowsPromptResourceDirectoryEntries(overlap, 1); err == nil {
		t.Fatal("overlapping next-entry offset was accepted")
	}
	misaligned := windowsPromptResourceDirectoryTestBuffer("x", 76, 80)
	if _, err := decodeWindowsPromptResourceDirectoryEntries(misaligned, 1); err == nil {
		t.Fatal("misaligned next-entry offset was accepted")
	}
}

func windowsPromptResourceDirectoryTestBuffer(name string, next uint32, minimumSize int) []byte {
	units := utf16.Encode([]rune(name))
	header := int(unsafe.Offsetof(windowsFileFullDirectoryInfo{}.FileName))
	size := header + len(units)*2
	if size < minimumSize {
		size = minimumSize
	}
	buffer := make([]byte, size)
	entry := (*windowsFileFullDirectoryInfo)(unsafe.Pointer(&buffer[0]))
	entry.NextEntryOffset = next
	entry.FileNameLength = uint32(len(units) * 2)
	copy(unsafe.Slice((*uint16)(unsafe.Pointer(&buffer[header])), len(units)), units)
	return buffer
}

func TestPrivateWindowsPromptResourceDescriptorDeduplicatesLocalSystem(t *testing.T) {
	system, err := windows.CreateWellKnownSid(windows.WinLocalSystemSid)
	if err != nil {
		t.Fatal(err)
	}
	descriptor, err := privateWindowsPromptResourceSecurityDescriptorFor([]*windows.SID{system})
	if err != nil {
		t.Fatal(err)
	}
	owner, _, err := descriptor.Owner()
	if err != nil {
		t.Fatal(err)
	}
	if owner == nil || !owner.Equals(system) {
		t.Fatalf("descriptor owner = %v, want LocalSystem", owner)
	}
	assertPromptStageACLEntries(t, descriptor, []*windows.SID{system}, true)
	if _, err := privateWindowsPromptResourceSecurityDescriptorFor([]*windows.SID{nil}); err == nil {
		t.Fatal("nil owner principal was accepted")
	}
}

func TestWindowsPromptResourceDirectoriesArePrivateAtCreation(t *testing.T) {
	parent, err := preparePromptResourceParent(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	_, _, rawGuard, err := createPromptResourceStage(parent)
	if err != nil {
		t.Fatal(err)
	}
	guard := rawGuard.(*windowsPromptResourceStageGuard)
	defer func() { _ = guard.Cleanup(nil) }()
	allowed, err := promptStageAllowedSIDs()
	if err != nil {
		t.Fatal(err)
	}
	if err := verifyPromptResourceStageACLHandle(guard.anchor.handle, allowed); err != nil {
		t.Fatalf("anchor ACL immediately after creation: %v", err)
	}
	if err := verifyPromptResourceStageACLHandle(guard.stage.handle, allowed); err != nil {
		t.Fatalf("stage ACL immediately after creation: %v", err)
	}
}

func TestWindowsPromptResourceGuardSupportsConfiguredInputsAboveDefault(t *testing.T) {
	const fileCount = DefaultMaxPromptResourceFiles + 2
	params := runtimeacp.PromptParams{Prompt: make([]runtimeacp.ContentBlock, 0, fileCount)}
	for index := 0; index < fileCount; index++ {
		params.Prompt = append(params.Prompt, runtimeacp.ContentBlock{
			Type:     "image",
			MimeType: "image/png",
			Name:     fmt.Sprintf("image-%d.png", index),
			Data:     base64.StdEncoding.EncodeToString([]byte{byte(index)}),
		})
	}
	prepared, stage, err := preparePromptResources(context.Background(), params, PromptResourceLimits{
		MaxFiles:      fileCount,
		MaxFileBytes:  1,
		MaxTotalBytes: fileCount,
	}, t.TempDir(), nil)
	if err != nil || stage == nil {
		t.Fatalf("prepare %d configured files: stage=%#v error=%v", fileCount, stage, err)
	}
	defer func() { _ = stage.cleanup() }()
	if len(prepared.Prompt) != fileCount {
		t.Fatalf("prepared prompt count = %d, want %d", len(prepared.Prompt), fileCount)
	}
	guard := stage.guard.(*windowsPromptResourceStageGuard)
	if len(guard.files) != fileCount || guard.expectedFiles != fileCount {
		t.Fatalf("guard files/expected = %d/%d, want %d/%d", len(guard.files), guard.expectedFiles, fileCount, fileCount)
	}
	if err := stage.verify(); err != nil {
		t.Fatalf("verify configured files above default: %v", err)
	}
}

func TestWindowsPromptResourceGuardBlocksReplacementAndRetainsCleanupRetry(t *testing.T) {
	params := runtimeacp.PromptParams{Prompt: []runtimeacp.ContentBlock{{
		Type:     "image",
		MimeType: "image/png",
		Data:     base64.StdEncoding.EncodeToString([]byte("image")),
	}}}
	root := t.TempDir()
	parent := filepath.Join(root, "trusted-parent")
	if err := os.Mkdir(parent, 0o700); err != nil {
		t.Fatal(err)
	}
	_, stage, err := preparePromptResources(context.Background(), params, PromptResourceLimits{}, parent, nil)
	if err != nil || stage == nil {
		t.Fatalf("prepare result stage=%#v err=%v", stage, err)
	}
	if err := os.Rename(stage.dir, stage.dir+"-replacement"); err == nil {
		t.Fatal("stage rename succeeded while delete-sharing protection was retained")
	}
	if err := os.Rename(stage.anchor, stage.anchor+"-replacement"); err == nil {
		t.Fatal("anchor rename succeeded while delete-sharing protection was retained")
	}
	if err := os.Rename(parent, parent+"-replacement"); err == nil {
		if restoreErr := os.Rename(parent+"-replacement", parent); restoreErr != nil {
			t.Fatalf("trusted ancestor rename unexpectedly succeeded and could not be restored: %v", restoreErr)
		}
		t.Fatal("trusted ancestor rename succeeded while no-delete-sharing protection was retained")
	}
	attempts := 0
	stage.cleanupHook = func(path string) error {
		attempts++
		if attempts == 1 {
			return errors.New("transient failure")
		}
		return nil
	}
	if err := stage.cleanup(); err != nil {
		t.Fatalf("bounded cleanup retry: %v", err)
	}
	if attempts != 2 {
		t.Fatalf("cleanup attempts = %d, want 2", attempts)
	}
}

func TestWindowsPromptResourceGuardRetainsFilesWithoutRequiringDeleteSharing(t *testing.T) {
	params := runtimeacp.PromptParams{Prompt: []runtimeacp.ContentBlock{{
		Type:     "image",
		MimeType: "image/png",
		Data:     base64.StdEncoding.EncodeToString([]byte("image")),
	}}}
	prepared, stage, err := preparePromptResources(context.Background(), params, PromptResourceLimits{}, t.TempDir(), nil)
	if err != nil || stage == nil {
		t.Fatalf("prepare result stage=%#v err=%v", stage, err)
	}
	defer func() { _ = stage.cleanup() }()
	directoryReader, err := os.Open(stage.dir)
	if err != nil {
		t.Fatalf("open staged directory without delete sharing: %v", err)
	}
	if _, err := directoryReader.Readdirnames(-1); err != nil {
		_ = directoryReader.Close()
		t.Fatalf("enumerate staged directory without delete sharing: %v", err)
	}
	if err := directoryReader.Close(); err != nil {
		t.Fatal(err)
	}
	path := prepared.Prompt[0].PreparedFile.Path
	path16, err := windows.UTF16PtrFromString(path)
	if err != nil {
		t.Fatal(err)
	}
	reader, err := windows.CreateFile(
		path16,
		windows.GENERIC_READ,
		windows.FILE_SHARE_READ,
		nil,
		windows.OPEN_EXISTING,
		windows.FILE_ATTRIBUTE_NORMAL,
		0,
	)
	if err != nil {
		t.Fatalf("open staged input without delete sharing: %v", err)
	}
	if err := windows.CloseHandle(reader); err != nil {
		t.Fatal(err)
	}
	if err := stage.verify(); err != nil {
		t.Fatalf("verify after agent-style read: %v", err)
	}
}

func TestWindowsPromptResourceCleanupAbandonsDirectoryGuardsAfterBoundedReaderFailure(t *testing.T) {
	params := runtimeacp.PromptParams{Prompt: []runtimeacp.ContentBlock{{
		Type:     "image",
		MimeType: "image/png",
		Data:     base64.StdEncoding.EncodeToString([]byte("image")),
	}}}
	_, stage, err := preparePromptResources(context.Background(), params, PromptResourceLimits{}, t.TempDir(), nil)
	if err != nil || stage == nil {
		t.Fatalf("prepare result stage=%#v err=%v", stage, err)
	}
	anchor := stage.anchor
	stageDir := stage.dir
	guard := stage.guard.(*windowsPromptResourceStageGuard)
	stagePath16, err := windows.UTF16PtrFromString(stage.dir)
	if err != nil {
		t.Fatal(err)
	}
	reader, err := windows.CreateFile(
		stagePath16,
		windows.GENERIC_READ,
		windows.FILE_SHARE_READ,
		nil,
		windows.OPEN_EXISTING,
		windows.FILE_FLAG_BACKUP_SEMANTICS,
		0,
	)
	if err != nil {
		t.Fatal(err)
	}
	if err := stage.cleanup(); err == nil {
		_ = windows.CloseHandle(reader)
		t.Fatal("cleanup succeeded while a reader denied delete sharing")
	}
	if stage.guard != nil || stage.dir != "" {
		_ = windows.CloseHandle(reader)
		t.Fatal("persistent cleanup failure did not abandon unreachable stage ownership")
	}
	if guard.stage.handle != windows.InvalidHandle || guard.anchor.handle != windows.InvalidHandle || len(guard.ancestors) != 0 {
		_ = windows.CloseHandle(reader)
		t.Fatal("persistent cleanup failure leaked retained Windows directory handles")
	}
	if err := windows.CloseHandle(reader); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(stageDir); err != nil {
		t.Fatalf("manually remove abandoned stage after reader closed: %v", err)
	}
	if err := os.Remove(anchor); err != nil {
		t.Fatalf("manually remove abandoned anchor after reader closed: %v", err)
	}
}

