		Message: "boom",
		Data:    map[string]any{"reason": "test"},
	})
	if err != nil {
		t.Fatalf("marshal local RPCError: %v", err)
	}
	want, err := json.Marshal(&sdk.RequestError{
		Code:    -32042,
		Message: "boom",
		Data:    map[string]any{"reason": "test"},
	})
	if err != nil {
		t.Fatalf("marshal sdk RequestError: %v", err)
